<!-- Generated by design-ui/bin/generate-review-demos.mjs; fixture: custom-status.vue. Edit the authored scenario, then regenerate. -->
<template>
  <DemoApiReviewPanel
    v-slot="__apiReview"
    v-bind="defineReviewConfig(__apiReviewRawConfig)"
  >
    <div ref="scroller" class="infinite-scroll-demo">
      <c-infinite-scroll
        v-model:status="status"
        :target="scroller"
        bottom-offset="2rem"
        v-bind="__apiReview.bindings"
        @load="fetchData"
        v-on="__apiReview.listeners"
      >
        <c-list :data="data" :scrollbar="false">
          <template #item="{ item }">
            <c-list-item>{{ item }}</c-list-item>
          </template>
        </c-list>

        <template v-if="__apiReview.slotEnabled['loading'] !== false" #loading>
          <c-space align="center">
            <c-loading />
            正在加载下一页
          </c-space>
        </template>
        <template v-if="__apiReview.slotEnabled['finished'] !== false" #finished
          >全部数据加载完成</template
        >
        <template v-if="__apiReview.slotEnabled['error']" #error="__reviewSlot"
          ><DemoReviewSlot
            name="error"
            :context="__reviewSlot"
            :controls="__apiReview.controls"
            :record="__apiReview.record" /></template
      ></c-infinite-scroll>
    </div>
  </DemoApiReviewPanel>
</template>

<script lang="ts" setup>
import DemoApiReviewPanel from "../../../docs/.vuepress/components/ApiReviewPanel.vue";
import {
  defineReviewConfig,
  ReviewSlot as DemoReviewSlot,
} from "@ui-foundation/ui-doc-preview";
import __apiReviewRawConfig from "./api-review.config.json";

import { onBeforeUnmount, onDeactivated, ref } from "vue";
import type { InfiniteScrollStatus } from "@cedarjs/ui";

const scroller = ref<HTMLElement>();
const data = ref<string[]>([]);
const status = ref<InfiniteScrollStatus>("idle");
let timer: ReturnType<typeof window.setTimeout> | undefined;

const fetchData = () => {
  window.clearTimeout(timer);
  timer = window.setTimeout(() => {
    timer = undefined;
    const start = data.value.length;
    data.value.push(
      ...Array.from(
        { length: 8 },
        (_, index) => `Cedar list item ${start + index + 1}`,
      ),
    );
    status.value = data.value.length >= 32 ? "finished" : "idle";
  }, 600);
};
onBeforeUnmount(() => window.clearTimeout(timer));
onDeactivated(() => {
  window.clearTimeout(timer);
  timer = undefined;
  if (status.value === "loading") {
    status.value = "idle";
  }
});
</script>

